/**
 * The predicate-range fact lattice must treat a zero kind or language bit set as <em>unknown</em> (the top element),
 * never as <em>none</em>: joining a known side with an unknown side yields unknown, meeting them yields the known side,
 * and only two known, disjoint sides prove emptiness. VALUES-seeded facts additionally carry the language and (XSD)
 * datatype knowledge their literals prove, so that widening a VALUES branch against a stored range stays precise.
 */
class PackedDomainFactLatticeTest {

	private static final IRI P = iri("p");
	private static final IRI Q = iri("q");
	private static final IRI R = iri("r");

	/**
	 * {@code :p} objects are proven language-free xsd:string literals; {@code :q} objects are literals of unknown
	 * language; {@code :r} objects are of unknown kind (a known range that only proves the datatype of its
	 * language-free literals).
	 */
	private static final PackedPredicateRangeProvider STRING_PROVIDER = new PackedPredicateRangeProvider() {
		@Override
		public boolean describeObjectRange(IRI predicate, PackedPredicateRange output) {
			if (P.equals(predicate)) {
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.setKindBits(PackedPredicateRange.KIND_LITERAL);
				output.setLanguageBits(PackedPredicateRange.LANGUAGE_WITHOUT);
				output.addDatatype(CoreDatatype.XSD.STRING);
				return true;
			}
			if (Q.equals(predicate)) {
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.setKindBits(PackedPredicateRange.KIND_LITERAL);
				return true;
			}
			if (R.equals(predicate)) {
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.addDatatype(CoreDatatype.XSD.INTEGER);
				return true;
			}
			return false;
		}

		@Override
		public long predicateRangeVersion() {
			return 17L;
		}
	};

	private final PackedObjectPool objects = new PackedObjectPool(16);
	private final PackedPredicateRangeArena arena = new PackedPredicateRangeArena();
	private final PackedDomainFacts facts = new PackedDomainFacts(arena, objects);
	private final PackedPredicateRange slot = new PackedPredicateRange();

	// ------------------------------------------------------------------ lattice join (widen)

	@Test
	void widenKnownLanguageWithUnknownLanguageIsUnknown() {
		int known = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITHOUT);
		int unknownLanguage = range(PackedPredicateRange.KIND_LITERAL, 0);

		int widened = facts.widen(known, unknownLanguage);

		assertEquals(PackedPredicateRange.STATE_KNOWN, arena.state(widened));
		assertEquals(PackedPredicateRange.KIND_LITERAL, arena.kindBits(widened));
		assertEquals(0, arena.languageBits(widened),
				"a branch of unknown language must not be reported as language-free");
	}

	@Test
	void widenKnownKindsWithUnknownKindsIsUnknown() {
		int known = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITHOUT);
		int unknownKinds = range(0, 0);

		int widened = facts.widen(known, unknownKinds);

		assertEquals(0, arena.kindBits(widened), "a branch of unknown kinds must not be reported as literal-only");
		assertEquals(0, arena.languageBits(widened));
	}

	@Test
	void widenDisjointKnownLanguagesIsTheirUnion() {
		int with = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITH);
		int without = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITHOUT);

		int widened = facts.widen(with, without);

		assertEquals(PackedPredicateRange.LANGUAGE_WITH | PackedPredicateRange.LANGUAGE_WITHOUT,
				arena.languageBits(widened));
	}

	@Test
	void widenIgnoresVacuousLanguageOfNonLiteralSide() {
		int iris = range(PackedPredicateRange.KIND_IRI, 0);
		int strings = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITHOUT);

		int widened = facts.widen(iris, strings);

		assertEquals(PackedPredicateRange.KIND_IRI | PackedPredicateRange.KIND_LITERAL, arena.kindBits(widened));
		assertEquals(PackedPredicateRange.LANGUAGE_WITHOUT, arena.languageBits(widened),
				"an IRI-only branch has no literals, so it cannot weaken the literal side's language proof");
	}

	// ------------------------------------------------------------------ lattice meet (intersect)

	@Test
	void intersectUnknownKindsWithKnownKindsKeepsTheKnownSide() {
		int unknown = range(0, 0);
		int iris = range(PackedPredicateRange.KIND_IRI, 0);

		int met = facts.intersect(unknown, iris);

		assertNotEquals(PackedPredicateRange.STATE_EMPTY, arena.state(met),
				"unknown kinds intersected with known kinds must not prove emptiness");
		assertEquals(PackedPredicateRange.KIND_IRI, arena.kindBits(met));
	}

	@Test
	void intersectUnknownLanguageWithKnownLanguageKeepsTheKnownSide() {
		int unknown = range(PackedPredicateRange.KIND_LITERAL, 0);
		int with = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITH);

		int met = facts.intersect(unknown, with);

		assertEquals(PackedPredicateRange.LANGUAGE_WITH, arena.languageBits(met));
	}

	@Test
	void intersectDisjointLanguagesOfLiteralOnlyRangesIsEmpty() {
		int with = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITH);
		int without = range(PackedPredicateRange.KIND_LITERAL, PackedPredicateRange.LANGUAGE_WITHOUT);

		assertEquals(PackedPredicateRange.STATE_EMPTY, arena.state(facts.intersect(with, without)));
	}

	@Test
	void intersectDisjointLanguagesDropsOnlyTheLiteralKind() {
		int with = range(PackedPredicateRange.KIND_LITERAL | PackedPredicateRange.KIND_IRI,
				PackedPredicateRange.LANGUAGE_WITH);
		int without = range(PackedPredicateRange.KIND_LITERAL | PackedPredicateRange.KIND_IRI,
				PackedPredicateRange.LANGUAGE_WITHOUT);

		int met = facts.intersect(with, without);

		assertEquals(PackedPredicateRange.STATE_KNOWN, arena.state(met));
		assertEquals(PackedPredicateRange.KIND_IRI, arena.kindBits(met), "IRIs survive; no literal can be in both");
		assertEquals(0, arena.languageBits(met));
	}

	@Test
	void intersectDisjointKnownKindsIsEmpty() {
		int iris = range(PackedPredicateRange.KIND_IRI, 0);
		int literals = range(PackedPredicateRange.KIND_LITERAL, 0);

		assertEquals(PackedPredicateRange.STATE_EMPTY, arena.state(facts.intersect(iris, literals)));
	}

	// ------------------------------------------------------------------ UNION with VALUES (reviewer's e2e shape)

	private static Model unionData() {
		Model data = model();
		add(data, "s1", "p", VF.createLiteral("x"));
		add(data, "s2", "p", VF.createLiteral("y"));
		return data;
	}

	@Test
	void unionWithLanguageTaggedValuesDoesNotProveWildcardLangMatchesFalse() {
		String query = "SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } FILTER(langMatches(lang(?o), \"*\")) }";
		assertNoRangeVerdict(query);
		assertPackedPlanPreservesResults(unionData(), query, SUBJECT_LOOKUP_COSTS, STRING_PROVIDER,
				List.of("o=\"a\"@en"));
	}

	@Test
	void unionWithLanguageTaggedValuesDoesNotProveEmptyLangTautological() {
		String query = "SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } FILTER(lang(?o) = \"\") }";
		assertNoRangeVerdict(query);
		assertPackedPlanPreservesResults(unionData(), query, SUBJECT_LOOKUP_COSTS, STRING_PROVIDER,
				List.of("o=\"x\"", "o=\"y\""));
	}

	@Test
	void subSelectUnionWithLanguageTaggedValuesDoesNotProveWildcardLangMatchesFalse() {
		String query = "SELECT ?o WHERE { { SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } } } "
				+ "FILTER(langMatches(lang(?o), \"*\")) }";
		assertNoRangeVerdict(query);
		assertPackedPlanPreservesResults(unionData(), query, SUBJECT_LOOKUP_COSTS, STRING_PROVIDER,
				List.of("o=\"a\"@en"));
	}

	@Test
	void subSelectUnionWithLanguageTaggedValuesDoesNotProveEmptyLangTautological() {
		String query = "SELECT ?o WHERE { { SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } } } "
				+ "FILTER(lang(?o) = \"\") }";
		assertNoRangeVerdict(query);
		assertPackedPlanPreservesResults(unionData(), query, SUBJECT_LOOKUP_COSTS, STRING_PROVIDER,
				List.of("o=\"x\"", "o=\"y\""));
	}

	@Test
	void unionOfLanguageFreeAndUnknownLanguageStoredRangesDoesNotProveWildcardLangMatchesFalse() {
		Model data = unionData();
		add(data, "s3", "q", VF.createLiteral("a", "en"));
		String query = "SELECT ?o WHERE { { ?s :p ?o } UNION { ?s :q ?o } FILTER(langMatches(lang(?o), \"*\")) }";
		assertNoRangeVerdict(query);
		assertPackedPlanPreservesResults(data, query, SUBJECT_LOOKUP_COSTS, STRING_PROVIDER, List.of("o=\"a\"@en"));
	}

	@Test
	void unionWithUnknownKindsDoesNotProveIsNumericFalse() {
		Model data = unionData();
		add(data, "s3", "r", VF.createLiteral("1", CoreDatatype.XSD.INTEGER));
		String query = "SELECT ?o WHERE { { ?s :p ?o } UNION { ?s :r ?o } FILTER(isNumeric(?o)) }";
		assertNoRangeVerdict(query);
		assertPackedPlanPreservesResults(data, query, SUBJECT_LOOKUP_COSTS, STRING_PROVIDER,
				List.of("o=\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>"));
	}

	@Test
	void knownNonLiteralKindsStillProveIsNumericFalse() {
		long mask = ruleMask("SELECT ?o WHERE { VALUES ?o { :a :b } FILTER(isNumeric(?o)) }");
		assertNotEquals(0L, mask & PackedRuleProofs.PREDICATE_RANGE_EMPTY,
				"IRIs are never numeric, so a range known to hold only IRIs proves the filter a contradiction");
	}

	// ------------------------------------------------------------------ VALUES seeding precision

	@Test
	void languageTaggedValuesProveWildcardLangMatchesTautological() {
		long mask = ruleMask(
				"SELECT ?o WHERE { VALUES ?o { \"a\"@en \"b\"@de } FILTER(langMatches(lang(?o), \"*\")) }");
		assertNotEquals(0L, mask & PackedRuleProofs.PREDICATE_RANGE_TAUTOLOGY,
				"every VALUES literal carries a language tag, so the filter is a proven tautology");
	}

	@Test
	void mixedLanguageValuesProveNothingAboutLang() {
		assertNoRangeVerdict("SELECT ?o WHERE { VALUES ?o { \"a\"@en \"b\" } FILTER(lang(?o) = \"\") }");
		assertNoRangeVerdict("SELECT ?o WHERE { VALUES ?o { \"a\"@en \"b\" } FILTER(langMatches(lang(?o), \"*\")) }");
	}

	@Test
	void languageFreeValuesProveEmptyLangTautological() {
		long mask = ruleMask("SELECT ?o WHERE { VALUES ?o { \"a\" \"b\" } FILTER(lang(?o) = \"\") }");
		assertNotEquals(0L, mask & PackedRuleProofs.PREDICATE_RANGE_TAUTOLOGY);
	}

	@Test
	void xsdTypedValuesProveTheirDatatype() {
		long mask = ruleMask("SELECT ?o WHERE { VALUES ?o { 1 2 } FILTER(datatype(?o) = xsd:integer) }");
		assertNotEquals(0L, mask & PackedRuleProofs.PREDICATE_RANGE_TAUTOLOGY,
				"both VALUES literals are xsd:integer, so the datatype test is a proven tautology");
		long disjoint = ruleMask("SELECT ?o WHERE { VALUES ?o { 1 2 } FILTER(datatype(?o) = xsd:string) }");
		assertNotEquals(0L, disjoint & PackedRuleProofs.PREDICATE_RANGE_EMPTY,
				"no xsd:integer literal has datatype xsd:string");
	}

	@Test
	void customDatatypeInValuesLeavesDatatypesUnknown() {
		assertNoRangeVerdict(
				"SELECT ?o WHERE { VALUES ?o { 1 \"x\"^^<urn:t:custom> } FILTER(datatype(?o) = xsd:integer) }");
	}

	/**
	 * Mirrors the stored-range convention (LMDB's {@code RdfTermDomain.classifyMask}): a language-tagged literal is
	 * described by {@code LANGUAGE_WITH} and contributes no datatype bit, so the datatype bits keep describing the
	 * language-free literals precisely.
	 */
	@Test
	void languageTaggedValuesKeepDatatypesOfLanguageFreeLiterals() {
		assertNoRangeVerdict("SELECT ?o WHERE { VALUES ?o { \"a\"@en 1 } FILTER(datatype(?o) = xsd:integer) }");
		long mask = ruleMask("SELECT ?o WHERE { VALUES ?o { \"a\"@en 1 } FILTER(datatype(?o) = xsd:string) }");
		assertNotEquals(0L, mask & PackedRuleProofs.PREDICATE_RANGE_EMPTY,
				"neither a language-tagged literal nor an xsd:integer has datatype xsd:string");
	}

	@Test
	void languageTaggedValuesDoNotProveTheirOwnDatatypeTautological() {
		assertNoRangeVerdict("SELECT ?o WHERE { VALUES ?o { \"a\"@en \"b\" } FILTER(datatype(?o) = xsd:string) }");
	}

	@Test
	void iriOnlyValuesProveLangAlwaysErrors() {
		long mask = ruleMask("SELECT ?o WHERE { VALUES ?o { :a :b } FILTER(lang(?o) = \"\") }");
		assertNotEquals(0L, mask & PackedRuleProofs.PREDICATE_RANGE_EMPTY,
				"lang() of an IRI is a type error for every row, so the filter drops everything");
	}

	// ------------------------------------------------------------------ helpers

	private int range(int kindBits, int languageBits) {
		slot.reset();
		slot.setState(PackedPredicateRange.STATE_KNOWN);
		slot.setKindBits(kindBits);
		slot.setLanguageBits(languageBits);
		return arena.intern(slot, objects);
	}

	private static long ruleMask(String query) {
		return generatedRuleMask(PackedQueryCodec.encodeForPlanning(parse(query), STRING_PROVIDER));
	}

	private static void assertNoRangeVerdict(String query) {
		long mask = ruleMask(query);
		assertEquals(0L, mask & (PackedRuleProofs.PREDICATE_RANGE_EMPTY | PackedRuleProofs.PREDICATE_RANGE_TAUTOLOGY),
				"no contradiction or tautology may be proven for " + query + " (generatedRuleMask=0x"
						+ Long.toHexString(mask) + ")");
	}
}
